import {chromium} from 'playwright';import {serveStatic} from '../../engine/static.mjs';
import assert from 'node:assert/strict';import {mkdtemp,cp,readFile,writeFile,rm,readdir} from 'node:fs/promises';import {tmpdir} from 'node:os';import path from 'node:path';import {load} from 'cheerio/slim';import {parseContent,YAML} from '../../scripts/source-project.mjs';import {run} from '../../engine/pipeline.mjs';
const root=path.resolve(process.argv[2]||'artifacts/platform/smartslider-installed'),temp=await mkdtemp(path.join(tmpdir(),'slider-authoring-'));
let browser,server;
try{
 await cp(path.join(root,'project'),temp,{recursive:true});for(const [source,target] of [['vendor/export-source.mjs','scripts/source.mjs'],['scripts/slider-authoring.mjs','scripts/slider-authoring.mjs']])await cp(new URL('../../'+source,import.meta.url),path.join(temp,target));const file=path.join(temp,'content/pages/home.md'),parsed=parseContent(await readFile(file,'utf8'),file),media=Object.values(parsed.meta.component_media||{});
 const first=media.find(m=>m.image.alt==='Abstract workshop scene 1'),second=media.find(m=>m.image.alt==='Abstract workshop scene 2');assert.ok(first&&second,'Slider images must have editable frontmatter');first.image={...second.image,alt:'Authored workshop artwork'};first.sources=structuredClone(second.sources);const sliderId=Object.keys(parsed.meta.slider_sequences||{})[0];assert.ok(sliderId,'Slider ordering must be editable');parsed.meta.slider_sequences[sliderId]=['3',{id:'authored-scene',template:'2',title:'New authored scene',image:{...second.image,alt:'New scene artwork'},sources:structuredClone(second.sources)},'1'];const templatesBefore=(await readdir(path.join(temp,'templates'),{recursive:true})).sort();
 await writeFile(file,'---\n'+YAML.stringify(parsed.meta)+'---\n\n'+parsed.body.replaceAll('Workshop scene 1','Authored first slide'));await run(process.execPath,['scripts/build.mjs'],{cwd:temp,timeout:120000});const $=load(await readFile(path.join(temp,'output/index.html'),'utf8'));
 assert.deepEqual($('.n2-ss-slide').map((_,el)=>$(el).attr('data-slide-public-id')).get(),['3','authored-scene','1']);assert.deepEqual($('.n2-ss-slide-background').map((_,el)=>$(el).attr('data-public-id')).get(),['3','authored-scene','1']);assert.equal($('.n2-ss-slide-active').attr('data-slide-public-id'),'3');assert.deepEqual((await readdir(path.join(temp,'templates'),{recursive:true})).sort(),templatesBefore);assert.equal($('.n2-ss-slide-background[data-public-id="authored-scene"] img').attr('alt'),'New scene artwork');assert.equal($('.n2-ss-slide[data-slide-public-id="authored-scene"] .n2-ss-slide--focus').text(),'New authored scene');const firstImage=$('.n2-ss-slide-background[data-public-id="1"] img');assert.equal(firstImage.attr('alt'),'Authored workshop artwork');assert.equal(firstImage.attr('src'),second.image.src);const sources=$('.n2-ss-slide-background[data-public-id="1"] source');assert.equal(sources.length,second.sources.length);for(const [i,attributes] of second.sources.entries())for(const [name,value] of Object.entries(attributes))assert.equal(sources.eq(i).attr(name),String(value));assert.match($('.n2-ss-slide[data-slide-public-id="1"]').text(),/Authored first slide/);assert.equal($('script[data-cloner-component=smart-slider]').length,1);assert.doesNotMatch($.html(),/MIGRATION_MEDIA_/);
 server=await serveStatic(path.join(temp,'output'));browser=await chromium.launch({channel:'chrome'});
 for(const width of [1440,390]){const page=await browser.newPage({viewport:{width,height:900},hasTouch:true,reducedMotion:'reduce'});await page.goto(server.url,{waitUntil:'networkidle'});const slider=page.locator('[data-cloner-smart-slider-ready=true]');await slider.waitFor();assert.equal(await slider.locator('.n2-ss-slide-active').getAttribute('data-slide-public-id'),'3');
  if(width===1440)await slider.locator('.nextend-arrow-next').click();else{const box=await slider.boundingBox(),cdp=await page.context().newCDPSession(page);await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:box.x+box.width*.8,y:box.y+box.height/2}]});for(let i=1;i<=8;i++){await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:box.x+box.width*(.8-.6*i/8),y:box.y+box.height/2}]});await page.waitForTimeout(25);}await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await cdp.detach();}
  await page.waitForFunction(()=>document.querySelector('.n2-ss-slide-active')?.dataset.slidePublicId==='authored-scene');assert.equal(await slider.locator('.n2-ss-slide-background[data-public-id="authored-scene"]').isVisible(),true);assert.equal(await slider.locator('.n2-ss-slide[data-slide-public-id="2"]').count(),0);await page.close();
 }
 const result={frontmatterImageAndAlt:true,responsiveCandidates:true,markdownSlideLabel:true,nativeBuild:true,reorderedAndRemovedSlides:true,desktopAndMobileSequenceNavigation:true,newImageSlide:true,noNewTemplateFiles:true,aiCalls:0,scope:'Edit/reorder/remove and add image slides from captured structures; layers/embedded IDs and wider configurations remain pending.'};await writeFile(path.join(root,'slider-authoring-check.json'),JSON.stringify(result,null,2));console.log(JSON.stringify(result));
}finally{await browser?.close();await server?.close();await rm(temp,{recursive:true,force:true});}
